using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;
public static class GridShiftV26Models {
 const string Folder="Assets/Generated/Editable26/";
 public static Dictionary<string,GameObject> Common(){var result=new Dictionary<string,GameObject>();var helper=new GameObject("Authoring helper");var fx=helper.AddComponent<GridShiftHomeRoutineFX>();Save("routine-hands",()=>fx.AuthorHandsModel(),result);Save("routine-water",()=>fx.AuthorParticleModel(true),result);Save("routine-steam",()=>fx.AuthorParticleModel(false),result);UnityEngine.Object.DestroyImmediate(helper);
 foreach(var part in new[]{("Cooking pan",PrimitiveType.Cylinder,new Vector3(.34f,.035f,.34f)),("Spoon",PrimitiveType.Cube,new Vector3(.025f,.025f,.28f)),("Plate",PrimitiveType.Cylinder,new Vector3(.23f,.015f,.23f)),("Food",PrimitiveType.Sphere,new Vector3(.13f,.045f,.13f)),("Fork",PrimitiveType.Cube,new Vector3(.015f,.015f,.19f))}){var p=part;Save("prop-"+p.Item1,()=>{var go=GameObject.CreatePrimitive(p.Item2);go.name=p.Item1;go.transform.localScale=p.Item3;go.GetComponent<Collider>().enabled=false;go.GetComponent<Renderer>().sharedMaterial=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=p.Item1=="Food"?new Color(.7f,.35f,.12f):new Color(.68f,.76f,.82f)};return go;},result);}
 Save("parcel",()=>{var go=UnityEngine.Object.Instantiate(Resources.Load<GameObject>("DeliveryPackage"));go.name="Editable delivery parcel";var id=go.GetComponent<GridShiftPackageIdentity>();if(id==null)id=go.AddComponent<GridShiftPackageIdentity>();id.AuthorScene();return go;},result);var avatars=Resources.Load<GridShiftAvatarCatalog>("GridShiftAvatarCatalog");if(avatars!=null)for(int i=0;i<avatars.models.Length;i++)result["avatar-"+i]=avatars.models[i];return result;}
 static void Save(string key,Func<GameObject> create,Dictionary<string,GameObject> result){string path=Folder+key.Replace(" ","-")+".prefab";var asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(asset==null){var go=create();GridShiftV26Authoring.PersistMaterials(go);asset=PrefabUtility.SaveAsPrefabAsset(go,path);UnityEngine.Object.DestroyImmediate(go);}if(key=="routine-hands"&&asset.GetComponent<GridShiftRoutinePalette>()==null){var contents=PrefabUtility.LoadPrefabContents(path);contents.AddComponent<GridShiftRoutinePalette>().AuthorScene();PrefabUtility.SaveAsPrefabAsset(contents,path);PrefabUtility.UnloadPrefabContents(contents);asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);}result[key]=asset;}
 public static GameObject Source(GameObject original,bool citizen){string path=AssetDatabase.GetAssetPath(original);if(path.StartsWith(Folder,StringComparison.Ordinal))return original;string id=AssetDatabase.AssetPathToGUID(path);string output=Folder+(citizen?"Citizen-":"Traffic-")+id+".prefab";var asset=AssetDatabase.LoadAssetAtPath<GameObject>(output);if(asset!=null)return asset;var go=UnityEngine.Object.Instantiate(original);go.name=original.name;if(citizen){var person=go.GetComponent<GridShiftCitizen>();if(person==null)person=go.AddComponent<GridShiftCitizen>();person.AuthorScene();GridShiftV26Authoring.MarkActions(go);}else{var box=go.GetComponent<BoxCollider>();if(box==null)box=go.AddComponent<BoxCollider>();var b=TrafficVehicleFactory.Measure(go);box.center=b.center;box.size=b.size;var lamps=go.GetComponent<GridShiftVehicleLamps>();if(lamps==null)lamps=go.AddComponent<GridShiftVehicleLamps>();lamps.AuthorScene();}GridShiftV26Authoring.PersistMaterials(go);asset=PrefabUtility.SaveAsPrefabAsset(go,output);UnityEngine.Object.DestroyImmediate(go);return asset;}
 public static void Install(Scene scene,Dictionary<string,GameObject> common){if(scene.GetRootGameObjects().Any(g=>g.GetComponent<GridShiftSceneTemplates>()!=null))return;var root=new GameObject("MODELOS EDITÁVEIS · fontes de objetos da partida");SceneManager.MoveGameObjectToScene(root,scene);root.transform.position=new Vector3(-80,8,0);var library=root.AddComponent<GridShiftSceneTemplates>();var entries=new List<GridShiftSceneTemplates.Entry>();GameObject Add(string key,GameObject asset){var frame=new GameObject(key).transform;frame.SetParent(root.transform,false);int index=entries.Count;frame.localPosition=new Vector3((index%6)*5,0,(index/6)*5);var model=(GameObject)PrefabUtility.InstantiatePrefab(asset,scene);model.transform.SetParent(frame,false);entries.Add(new GridShiftSceneTemplates.Entry{key=key,model=model});return model;}
 foreach(var pair in common)Add(pair.Key,pair.Value);
 foreach(var pedestrian in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<PedestrianManager>(true))){for(int i=0;i<pedestrian.models.Length;i++)pedestrian.models[i]=Add("citizen-"+i,Source(pedestrian.models[i],true));EditorUtility.SetDirty(pedestrian);}
 foreach(var traffic in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<TrafficManager>(true))){var data=new SerializedObject(traffic);var models=data.FindProperty("modelos");for(int i=0;i<models.arraySize;i++){var entry=models.GetArrayElementAtIndex(i);var slot=entry.FindPropertyRelative("prefab");var original=slot.objectReferenceValue as GameObject;if(original==null)continue;slot.objectReferenceValue=Add("traffic-"+i,Source(original,false));entry.FindPropertyRelative("usePrefabCollider").boolValue=true;}data.ApplyModifiedPropertiesWithoutUndo();}
 foreach(var car in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<TrafficCar>(true))){var lamp=car.GetComponent<GridShiftVehicleLamps>();if(lamp==null)lamp=car.gameObject.AddComponent<GridShiftVehicleLamps>();lamp.AuthorScene();}
 library.models=entries.ToArray();}
}
